package com.adib.maintenance;
import android.view.*;import android.widget.*;import android.app.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.*;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={24,28,35}) public class SettingsZoomTest{
JSONObject prior;boolean required;
@Before public void before()throws Exception{prior=AccountSession.user;required=AccountSession.required;AccountSession.user=new JSONObject().put("id","test").put("name","Ilqar").put("role","employee");AccountSession.required=true;}
@After public void after(){AccountSession.user=prior;AccountSession.required=required;}
void set(Object a,String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}Object get(Object a,String n)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}void call(Object a,String n)throws Exception{Method m=a.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
@Test public void employeeSettingsShowsChoicesWithoutLaunchingTasks()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();call(a,"showSettings");AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertNotNull(d);assertTrue(d.isShowing());assertNull(Shadows.shadowOf(a).getNextStartedActivity());assertEquals("Cihaz parametrləri",d.getListView().getAdapter().getItem(0));assertEquals("Hesab və profil",d.getListView().getAdapter().getItem(1));}
@Test public void administratorSettingsAlsoStartsWithDeviceOptions()throws Exception{AccountSession.user.put("role","admin");MainActivity a=Robolectric.buildActivity(MainActivity.class).get();call(a,"showSettings");AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Hesab və işçilər",d.getListView().getAdapter().getItem(1));assertNull(Shadows.shadowOf(a).getNextStartedActivity());}
MainActivity equipment()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"mode","equipment");set(a,"screen","canvas");set(a,"plans",new JSONArray().put(new JSONObject().put("id","root").put("name","ADIB")).put(new JSONObject().put("id","p").put("name","Aşağı zavod").put("parentId","root").put("width",190).put("height",125)));call(a,"render");View root=(View)get(a,"root");root.measure(View.MeasureSpec.makeMeasureSpec(390,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(760,View.MeasureSpec.EXACTLY));root.layout(0,0,390,760);return a;}
void event(View v,int action,long t,float...xs){int n=xs.length;MotionEvent.PointerProperties[] props=new MotionEvent.PointerProperties[n];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[n];for(int i=0;i<n;i++){props[i]=new MotionEvent.PointerProperties();props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=xs[i];coords[i].y=150;coords[i].pressure=1;coords[i].size=1;}MotionEvent e=MotionEvent.obtain(1,t,action,n,props,coords,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);v.dispatchTouchEvent(e);e.recycle();}
@Test public void realTwoFingerPinchChangesScaleAndDoesNotNavigate()throws Exception{MainActivity a=equipment();View v=((View)get(a,"root")).findViewWithTag("equipment-canvas");float initial=(Float)get(v,"scale");event(v,MotionEvent.ACTION_DOWN,1,100);event(v,MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),20,100,150);event(v,MotionEvent.ACTION_MOVE,40,80,170);assertTrue((Float)get(v,"scale")>initial);event(v,MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),60,80,170);event(v,MotionEvent.ACTION_UP,70,80);assertEquals("",get(a,"currentPlanId"));assertEquals("canvas",get(a,"screen"));}
@Test public void zoomButtonsAndBackgroundRebuildPreserveCamera()throws Exception{MainActivity a=equipment();View root=(View)get(a,"root"),v=root.findViewWithTag("equipment-canvas");float initial=(Float)get(v,"scale");root.findViewWithTag("equipment-zoom:2").performClick();float zoomed=(Float)get(v,"scale");assertTrue(zoomed>initial);call(a,"render");root=(View)get(a,"root");root.measure(View.MeasureSpec.makeMeasureSpec(390,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(760,View.MeasureSpec.EXACTLY));root.layout(0,0,390,760);v=root.findViewWithTag("equipment-canvas");assertEquals(zoomed,(Float)get(v,"scale"),.001);root.findViewWithTag("equipment-zoom:0").performClick();assertEquals(initial,(Float)get(v,"scale"),.001);root.findViewWithTag("equipment-zoom:2").performClick();root.findViewWithTag("equipment-zoom:1").performClick();assertEquals(initial,(Float)get(v,"scale"),.001);}
}
